from fractions import Fraction


def _floor_log2(fr):
    # fr is a positive Fraction
    c = fr.numerator.bit_length() - fr.denominator.bit_length()
    # adjust
    if Fraction(2) ** c > fr:
        c -= 1
    elif Fraction(2) ** (c + 1) <= fr:
        c += 1
    return c


